<?php if($reviews['total']): ?><div class="pdp-rating-summary"><strong><?= intdiv($reviews['rating_tenths'],10) ?>.<?= $reviews['rating_tenths']%10 ?> ★</strong><span><?= $e($reviews['total']) ?> verified-purchase <?= $reviews['total']===1?'review':'reviews' ?></span></div><div class="pdp-rating-bars"><?php for($star=5;$star>=1;$star--): ?><div><span><?= $star ?> ★</span><meter min="0" max="<?= $e($reviews['total']) ?>" value="<?= $e($reviews['breakdown'][$star]) ?>" aria-label="<?= $star ?> star reviews"></meter><span><?= $e($reviews['breakdown'][$star]) ?></span></div><?php endfor; ?></div><?php else: ?><p>No published reviews yet. Share your experience after your order is delivered.</p><?php endif; ?>
<?php foreach($reviews['items'] as $review): ?><article class="pdp-review"><strong><?= $e($review['rating']) ?> ★ · <?= $e($review['title']) ?></strong><p><?= $e($review['body']) ?></p><small><?= $e($review['author']?:'Customer') ?> · Verified purchase · <?= $e(gmdate('d M Y',(int)$review['created_at'])) ?></small></article><?php endforeach; ?>
